  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਦੇ ਕੇਂਦਰੀ ਭਾਵ ਦੀ ਵਿਸਥਾਰ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੰਨਿਆ ਭਰੂਣ ਹੱਤਿਆ ਇੱਕ ਸਮਾਜਿਕ ਸਮੱਸਿਆ ਕਿਵੇਂ ਹੈ ਅਤੇ ਇਸ ਦੇ ਸਮਾਜ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦੇ ਹਨ? ਵਿਸਥਾਰ ਨਾਲ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਂ ਅਤੇ ਧੀ ਦੇ ਰਿਸ਼ਤੇ ਦੀ ਮਹੱਤਤਾ ਨੂੰ ਕਵਿਤਾ ਦੇ ਪ੍ਰਸੰਗ ਵਿੱਚ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਵਰਤੇ ਗਏ ਤਿਉਹਾਰਾਂ (ਰੱਖੜੀ, ਤੀਆਂ) ਦਾ ਧੀਆਂ ਦੀ ਹੋਂਦ ਨਾਲ ਕੀ ਸੰਬੰਧ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$“ਮਾਵਾਂ-ਧੀਆਂ ਮਿਲ ਕੇ ਹੌਲਾ ਕਰਨ ਦਿਲਾਂ ਦਾ ਭਾਰ ਨੀ ਅੰਮੀਏ” ਸਤਰ ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਕਵੀ ਸਮਾਜ ਨੂੰ ਕੀ ਸੰਦੇਸ਼ ਦੇਣਾ ਚਾਹੁੰਦਾ ਹੈ? ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਵਰਤੇ ਗਏ ਅਲੰਕਾਰਾਂ ਦੀ ਪਛਾਣ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਦੇ ਭਾਸ਼ਾਈ ਪੱਖ 'ਤੇ ਚਾਨਣਾ ਪਾਓ। (ਠੇਠ ਪੰਜਾਬੀ, ਸ਼ਬਦਾਵਲੀ ਆਦਿ)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪ੍ਰਗਟਾਏ ਗਏ ਦਰਦ ਅਤੇ ਚਿੰਤਾ ਦੇ ਭਾਵਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਦੇ ਸਿੱਖਣ ਨਤੀਜਿਆਂ (Learning Outcomes) ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਦੇ ਆਧਾਰ 'ਤੇ ਦੱਸੋ ਕਿ ਧੀਆਂ ਤੋਂ ਬਿਨਾਂ ਸਮਾਜ ਕਿਹੋ ਜਿਹਾ ਹੋ ਜਾਵੇਗਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ 'ਤ੍ਰਿੰਝਣ' ਅਤੇ 'ਤੀਆਂ' ਦੇ ਜ਼ਿਕਰ ਦਾ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵੀ ਨੇ 'ਮੇਰੇ ਦਿਲ ਦੀ ਜਾਨ ਲੈ ਅੰਮੀਏ' ਕਹਿ ਕੇ ਕਿਹੜੇ ਭਾਵ ਪ੍ਰਗਟ ਕੀਤੇ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੰਨਿਆ ਭਰੂਣ ਹੱਤਿਆ ਨੂੰ ਰੋਕਣ ਲਈ ਸਰਕਾਰ ਅਤੇ ਸਮਾਜ ਕੀ ਕਦਮ ਚੁੱਕ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
