  ('d2d77fa3-d523-4289-9367-65c7521becae', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਏਂ ਜੇ ਜੱਗ ਉੱਤੇ ਲੋਕੀਂ ਸਾਰੇ ਮਾਰਨ ਲੱਗ ਪਏ ਧੀਆਂ, ਕਿੱਦਾਂ ਫੇਰ ਤ੍ਰਿੰਝਣ ਲੱਗੂ ਕੌਣ ਮਨਾਊ ਤੀਆਂ, ਤੀਆਂ, ਰੱਖੜੀ ਸਭ ਭੁੱਲ ਜਾਣੇ, ਭੁੱਲ ਜਾਣੇ ਤਿਉਹਾਰ ਨੀ ਅੰਮੀਏ, ਕਿਸ ਨੂੰ ਦੱਸਾਂ ਮਾਂ ਤੇ ਧੀ ਦੇ ਰਿਸ਼ਤੇ ਵਰਗਾ ਦੱਸੋ ਰਿਸ਼ਤਾ ਕਿਹੜਾ, ਇੱਕ ਦੂਜੇ ਦੇ ਦੁੱਖੜੇ ਸੁਣ ਕੇ ਦਰਦ ਵੰਡਾਵੇ ਜਿਹੜਾ, ਮਾਵਾਂ-ਧੀਆਂ ਮਿਲ ਕੇ ਹੌਲਾ ਕਰਨ ਦਿਲਾਂ ਦਾ ਭਾਰ ਨੀ ਅੰਮੀਏ, ਕਿਸ ਨੂੰ ਦੱਸਾਂ ਦਰਦ ਕਹਾਣੀ, ਮੇਰੇ ਦਿਲ ਦੀ ਜਾਨ ਲੈ ਅੰਮੀਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('881796a9-83a3-4159-ae90-5e51255c366a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਏਂ ਜੇ ਜੱਗ ਉੱਤੇ ਲੋਕੀਂ ਸਾਰੇ ਮਾਰਨ ਲੱਗ ਪਏ ਧੀਆਂ, ਕਿੱਦਾਂ ਫੇਰ ਤ੍ਰਿੰਝਣ ਲੱਗੂ ਕੌਣ ਮਨਾਊ ਤੀਆਂ, ਤੀਆਂ, ਰੱਖੜੀ ਸਭ ਭੁੱਲ ਜਾਣੇ, ਭੁੱਲ ਜਾਣੇ ਤਿਉਹਾਰ ਨੀ ਅੰਮੀਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
