  ('0324f348-78ea-4931-95f7-083d8bcee347', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਰਦ - ਦੁੱਖ; ਪੁਕਾਰ - ਫਰਿਆਦ; ਅੰਮੀਏ - ਮਾਂ; ਖੋਰੇ - ਸ਼ਾਇਦ; ਅਹੁਦਾ - ਪਦਵੀ; ਦੋਸ਼ - ਕਸੂਰ; ਬਾਝੋਂ - ਬਿਨਾਂ; ਸੋਹੰਦਾ - ਸੋਹਣਾ ਲੱਗਦਾ; ਜੰਝ - ਬਰਾਤ; ਢੁੱਕੂ - ਆਵੇ; ਹੋਂਦ - ਮੌਜੂਦਗੀ; ਸੁੰਨੇ - ਸੁੰਨਸਾਨ, ਉਜਾੜ; ਤੀਆਂ - ਸਾਵਣ ਦੇ ਮਹੀਨੇ ਮਨਾਇਆ ਜਾਣ ਵਾਲਾ ਇੱਕ ਤਿਉਹਾਰ; ਹੌਲਾ ਕਰਨਾ - ਘਟਾਉਣਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4093196f-3b78-433a-afe6-9599eb7bf7c9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '98504c54-7571-4c9a-ac7b-dd90137d5106', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਸਮਾਜਿਕ ਸਮੱਸਿਆਵਾਂ ਸੰਬੰਧੀ ਜਾਣਕਾਰੀ ਵਿੱਚ ਵਾਧਾ। * ਕੁੜੀਆਂ ਨੂੰ ਮੁੰਡਿਆਂ ਦੇ ਸਮਾਨ ਸਮਾਜਿਕ ਦਰਜਾ ਦੇਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-047Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
